using System.Text;
using System.Text.Json.Nodes;
using System.Net.WebSockets;

namespace WindowsBlocker.Bridge;

public sealed partial class ConnectionHub
{
    // This identity is generated by the host's creator-owned process session,
    // never by a JSON field received over the pipe or a browser connection.
    public Func<(long Generation, bool Supported)>? ActivitySettingsAuthority { get; set; }
    private long _activitySettingsAuthorityGeneration;
    private bool _activitySettingsAuthoritySupported;
    private string? _activitySettingsEpoch;
    private long _activitySettingsRevision = -1;
    private const long MaxJavaScriptInteger = 9_007_199_254_740_991;

    public Task ResetActivitySettingsAuthority(long generation)
    {
        Task[] closes;
        lock (_gate)
        {
            var current = ActivitySettingsAuthority?.Invoke();
            if (current is not { } authority || generation <= 0 || generation < _activitySettingsAuthorityGeneration || authority.Generation != generation)
                return Task.CompletedTask;
            var newer = generation > _activitySettingsAuthorityGeneration;
            if (!newer && authority.Supported == _activitySettingsAuthoritySupported) return Task.CompletedTask;
            if (newer) { _activitySettingsEpoch = null; _activitySettingsRevision = -1; }
            _activitySettingsAuthorityGeneration = generation;
            _activitySettingsAuthoritySupported = authority.Supported;
            closes = DisconnectActivityBrowsersLocked();
        }
        return Task.WhenAll(closes);
    }

    // Caller holds the same gate used by generation reset, commit admission and
    // welcome capture. A stale callback cannot change the current epoch.
    private bool ActivitySettingsSupported()
    {
        var current = ActivitySettingsAuthority?.Invoke();
        return current is { } authority && _activitySettingsAuthoritySupported && authority.Generation == _activitySettingsAuthorityGeneration && authority.Supported;
    }

    private Task[] DisconnectActivityBrowsersLocked() =>
        _peers.Values.Where(p => p.Connected && LocalHubAuthentication.BrowserPrograms.Contains(p.Program)).Select(peer =>
        {
            peer.Connected = false;
            peer.BrowserIdentity = null;
            peer.ClosingForWorker = true;
            // CloseOutput shares the normal send FIFO, behind accepted frames.
            lock (peer.SendGate)
                return peer.SendTail = peer.SendTail.ContinueWith(async _ =>
                {
                    try { if (peer.Socket.State == WebSocketState.Open) await peer.Socket.CloseOutputAsync(WebSocketCloseStatus.NormalClosure, "worker-session-changed", CancellationToken.None); }
                    catch (Exception ex) { System.Diagnostics.Trace.WriteLine("Activity reconnect close: " + ex.Message); }
                    finally { Remove(peer); }
                }, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.Default).Unwrap();
        }).ToArray();

    public bool PublishActivitySettings(long generation, JsonObject body)
    {
        if (!ValidActivitySettingsBody(body, out var epoch, out var revision)) return false;
        lock (_gate)
        {
            if (generation != _activitySettingsAuthorityGeneration || !ActivitySettingsSupported() ||
                (_activitySettingsEpoch == epoch && revision <= _activitySettingsRevision)) return false;
            _activitySettingsEpoch = epoch;
            _activitySettingsRevision = revision;
            var frame = new JsonObject { ["kind"] = "activity-settings-updated", ["body"] = body.DeepClone() };
            foreach (var peer in _peers.Values.Where(p => p.Connected && LocalHubAuthentication.BrowserPrograms.Contains(p.Program)))
                _ = SendAsync(peer, frame);
            return true;
        }
    }

    internal static JsonObject ActivitySettingsResponse(JsonNode? response)
    {
        if (response is not JsonObject body || Text(body["kind"]) != "settings" || !ValidActivitySettingsBody(body, out _, out _))
            throw new InvalidDataException("invalid-activity-settings-response");
        var answer = new JsonObject();
        foreach (var key in new[] { "settings", "epoch", "revision", "changedAtMs" }) answer[key] = body[key]!.DeepClone();
        return answer;
    }

    internal static JsonObject ActivityRecordResponse(JsonNode? response)
    {
        if (response is not JsonObject body || Text(body["kind"]) != "recorded" ||
            body["accepted"] is not JsonValue count || !count.TryGetValue<long>(out var stored) || stored < 0 ||
            body["acceptedIDs"] is not JsonArray || body["rejectedIDs"] is not JsonArray || body["pendingIDs"] is not JsonArray)
            throw new InvalidDataException("invalid-activity-record-response");
        var answer = new JsonObject { ["stored"] = body["accepted"]!.DeepClone() };
        foreach (var key in new[] { "acceptedIDs", "rejectedIDs", "pendingIDs" }) answer[key] = body[key]!.DeepClone();
        return answer;
    }

    private static bool ValidActivitySettingsBody(JsonObject body, out string? epoch, out long revision)
    {
        epoch = null; revision = -1;
        if (body["settings"] is not JsonObject ||
            body["epoch"] is not JsonValue epochValue || !epochValue.TryGetValue<string>(out epoch) ||
            !Guid.TryParseExact(epoch, "D", out _) ||
            body["revision"] is not JsonValue revisionValue || !revisionValue.TryGetValue<long>(out revision) ||
            revision < 0 || revision > MaxJavaScriptInteger ||
            body["changedAtMs"] is not JsonValue timeValue || !timeValue.TryGetValue<double>(out var changedAt) ||
            !double.IsFinite(changedAt) || changedAt < 0 || changedAt > MaxJavaScriptInteger ||
            Encoding.UTF8.GetByteCount(body.ToJsonString()) > 88_000) return false;
        return true;
    }
}
